import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./css/navigation.css"; // Import external CSS

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState("default-avatar.png"); // Default avatar

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      try {
        const owner = JSON.parse(ownerData);
        setAvatar(owner.avatar || "default-avatar.png");
      } catch (error) {
        console.error("Error parsing owner data:", error);
      }
    }

    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, []);

  useEffect(() => {
    setTimeout(() => {
      document.body.classList.add("loaded");
    }, 100);
  }, []);
  

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    setIsLoggedIn(false);
    setAvatar("default-avatar.png");
    window.location.reload();
  };

  const handleAvatarClick = () => {
    setDropdownVisible(true);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem("ownerId");
    if (ownerId) {
      navigate(`/profile/${ownerId}`);
    }
  };

  return (
    <nav id="menu" className="navbar navbar-default">
      <div className="container">
        <div className="navbar-header">
          <button
            type="button"
            className="navbar-toggle collapsed"
            data-toggle="collapse"
            data-target="#bs-example-navbar-collapse-1"
          >
            <span className="sr-only">Toggle navigation</span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
            <span className="icon-bar"></span>
          </button>
          <a className="navbar-brand page-scroll" href="#page-top">
            <img src={require("../assets/Logo.png")} alt="Petopia Logo" className="logo" />
          </a>
        </div>

        <div className="collapse navbar-collapse" id="bs-example-navbar-collapse-1">
          <ul className="nav navbar-nav navbar-right">
            {!isLoggedIn ? (
              <>
                <li>
                  <a href="/#header" className="page-scroll nav-link">Home</a>
                </li>
                <li>
                  <Link to="/login" className="nav-link">Log In</Link>
                </li>
              </>
            ) : (
              <li className="dropdown-container" ref={dropdownRef}>
                <img
                  src={avatar}
                  alt="Profile"
                  className="avatar"
                  onClick={handleAvatarClick}
                />
                {dropdownVisible && (
                  <div className="dropdown-menu">
                    <div className="dropdown-item" onClick={handleProfileClick}>Profile</div>
                    <div className="dropdown-item" onClick={handleLogout}>Logout</div>
                  </div>
                )}
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
